export type HelpBadge = "ADMIN" | "CONDITIONAL" | "INFORMATIONAL";

export interface HelpEntry {
  id: string;
  label: string;
  icon: LucideIcon;
  location: string;
  description: string;
  badges?: HelpBadge[];
}

export interface HelpSection {
  id: string;
  title: string;
  summary: string;
  entries: HelpEntry[];
}

const entry = (
  id: string,
  label: string,
  icon: LucideIcon,
  location: string,
  description: string,
  badges?: HelpBadge[]
): HelpEntry => ({ id, label, icon, location, description, badges });

